const token = pm.response.json().token;
pm.sendRequest({
    url: pm.collectionVariables.get("URL") + "/api/v1/auth/me",
    method: "GET",
    header: { Authorization: "Bearer " + token }
}, (err, res) => {
    pm.test("role is user, not admin", () => {
        pm.expect(err).to.eql(null);
        pm.expect(res.json().data.role).to.eql("user");
    });
});

